classdef pgfGridTest < matlab.unittest.TestCase
    % Phase-1 tests for the PGF sparse-grid core (src/+ssit/+pgf).
    % Compares the MATLAB port with reference data exported from Edward's
    % Julia implementation (tests/test_data/pgf/pgf_grids.mat, generated by
    % PGFfromEdward/export_pgf_fixtures.jl; see the README in that folder).
    %
    % Run from the tests folder:
    %   results = runtests('pgfGridTest')

    properties (TestParameter)
        caseName = {'d1_mu3','d2_iso2','d2_aniso31','d3_aniso212','d4_grdusp1'};
    end

    properties
        Fixtures
    end

    methods (TestClassSetup)
        function loadFixtures(testCase)
            here = fileparts(mfilename('fullpath'));
            addpath(genpath(fullfile(here, '..', 'src')));
            F = load(fullfile(here, 'test_data', 'pgf', 'pgf_grids.mat'));
            testCase.Fixtures = F.cases;
        end
    end

    methods (Static)
        function [sg, ref] = buildCase(fixtures, name)
            ref = fixtures.(name);
            mu = ref.mu(:)';
            if ref.mu_is_isotropic_integer
                mu = mu(1);   % scalar mu selects the isotropic multi-index generator
            end
            sg = ssit.pgf.buildGrid(mu, ref.domain, hessian=isfield(ref, 'H'));
        end

        function e = relErr(A, B)
            e = max(abs(A(:) - B(:))) / max(1, max(abs(B(:))));
        end
    end

    methods (Test)
        function gridMatchesJulia(testCase, caseName)
            [sg, ref] = pgfGridTest.buildCase(testCase.Fixtures, caseName);
            testCase.verifyEqual(sg.N, ref.N);
            testCase.verifyEqual(sg.multiIndex, ref.multi_index);           % exact
            testCase.verifyLessThanOrEqual(max(abs(sg.z - ref.grid), [], 'all'), 1e-14);
            testCase.verifyEqual(sg.oneIndex, ref.one_index);
        end

        function matricesMatchJulia(testCase, caseName)
            [sg, ref] = pgfGridTest.buildCase(testCase.Fixtures, caseName);
            % Python mirror of this code agrees with Julia to <= 1.1e-15 relative.
            testCase.verifyLessThanOrEqual(pgfGridTest.relErr(sg.invInterp, ref.inv_interp_mat), 1e-12);
            testCase.verifyLessThanOrEqual(pgfGridTest.relErr(sg.D, ref.D), 1e-12);
            if isfield(ref, 'H')
                testCase.verifyLessThanOrEqual(pgfGridTest.relErr(sg.H, ref.H), 1e-12);
            end
        end

        function interpolantReproducesNodeValues(testCase, caseName)
            sg = pgfGridTest.buildCase(testCase.Fixtures, caseName);
            G = cos((1:sg.N)' * [1 2]);
            V = ssit.pgf.interpolate(sg, G, sg.z);
            testCase.verifyLessThanOrEqual(max(abs(V - G), [], 'all'), 1e-12);
        end

        function derivativesExactOnPolynomial(testCase, caseName)
            % f = prod(z) + z1^2 lies in the interpolation space when every
            % multi-index row can reach level >= 2 in all dimensions at once,
            % which fails for d3_aniso212 (max(mu) < d): skip that case.
            sg = pgfGridTest.buildCase(testCase.Fixtures, caseName);
            testCase.assumeTrue(sg.oneIndex > 0, 'grid cannot represent prod(z)');
            z = sg.z;
            f = prod(z, 2) + z(:,1).^2;
            for i = 1:sg.d
                exact = prod(z(:, setdiff(1:sg.d, i)), 2) + (i == 1) * 2 * z(:,1);
                testCase.verifyLessThanOrEqual(max(abs(sg.D(:,:,i) * f - exact)), 1e-10);
            end
        end
    end

    methods (Test)
        function domainOrientationIsIrrelevant(testCase)
            dom = [1 1; 0.9 0.8];
            a = ssit.pgf.buildGrid([3 1], dom);
            b = ssit.pgf.buildGrid([3 1], flipud(dom));
            testCase.verifyEqual(b.z, a.z);
            testCase.verifyEqual(b.D, a.D);
        end

        function scalarMuEqualsRepeatedVector(testCase)
            % The isotropic generator (scalar mu) and the anisotropic one with
            % mu = repmat(mu,1,d) give the same multi-index, row order included.
            for d = 2:4
                for mu = 1:3
                    testCase.verifyEqual(ssit.pgf.smolyakMultiIndex(d, mu), ...
                        ssit.pgf.smolyakMultiIndex(d, repmat(mu,1,d)), ...
                        sprintf('d = %d, mu = %d', d, mu));
                end
            end
        end

        function interpolateAtOneWithoutOneNode(testCase)
            % max(mu) < d: no z = 1 node, evaluate through the interpolant.
            % Poisson PGF with means m: G(1) = 1, dG/dz1(1) = m1 = 3.  On this
            % coarse grid the Python mirror gives 0.99975 and 2.9888.
            sg = ssit.pgf.buildGrid([2 1 2], [1 1 1; 0.95 0.9 0.85]);
            testCase.verifyEqual(sg.oneIndex, 0);
            m = [3; 0.5; 2];
            G = exp((sg.z - 1) * m);
            testCase.verifyEqual(ssit.pgf.interpolate(sg, G, ones(1,3)), 1, 'AbsTol', 1e-3);
            testCase.verifyEqual(ssit.pgf.interpolate(sg, G, ones(1,3), [1 0 0]), 3, 'AbsTol', 2e-2);
        end
    end
end
